// ---- relocatability, enforced: the wire is a pure length-prefixed
// stream AND the decoded storage is pointer-free — every closure type
// must stay trivially copyable and standard-layout, so instances can be
// memcpy'd, mmap'd, shared across processes, and walked through
// descriptor offsets. A failure here means a pointer, virtual or
// non-trivial member crept into generated storage.
//
// They ask the COMPILER ITSELF, which is what every C++ standard library
// answers the same two questions with — and it costs this header no
// include at all.
static_assert( __is_trivially_copyable( GunnerSettings ), "GunnerSettings must stay relocatable" );
static_assert( __is_standard_layout( GunnerSettings ), "GunnerSettings must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( ShipEntry ), "ShipEntry must stay relocatable" );
static_assert( __is_standard_layout( ShipEntry ), "ShipEntry must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( GlobalSettings ), "GlobalSettings must stay relocatable" );
static_assert( __is_standard_layout( GlobalSettings ), "GlobalSettings must stay standard-layout for offsetof" );
static_assert( __is_trivially_copyable( PackConfig ), "PackConfig must stay relocatable" );
static_assert( __is_standard_layout( PackConfig ), "PackConfig must stay standard-layout for offsetof" );

// ---- the cook's layout contract (docs/SPEC-TABLES.md §20.3) ----
//
// The compiler derived every number below from the declaration and folded it
// into the BUILD VERSION; these asserts are this compiler saying whether it
// agrees. The model is not self-evidently right — on 32-bit System V
// alignof(uint64_t) is 4, not 8 — which is precisely why it is asserted
// rather than assumed.
static_assert( sizeof( GunnerSettings ) == 36, "GunnerSettings's sizeof moved: the build version was taken over 36, so a cook of it would not be this build's file (docs/SPEC-TABLES.md §20.3)" );
static_assert( alignof( GunnerSettings ) == 4, "GunnerSettings's alignof moved: the build version was taken over 4 (docs/SPEC-TABLES.md §20.3)" );
